import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final celsius=TextEditingController();String resultado='';void converter(){final c=double.tryParse(celsius.text.replaceAll(',','.'));setState(()=>resultado=c==null?'Informe uma temperatura válida.':'Temperatura em Fahrenheit: ${(c*9/5+32).toStringAsFixed(1)} °F');}void limpar(){celsius.clear();setState(()=>resultado='');}@override void dispose(){celsius.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Conversor de temperatura')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:celsius,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Temperatura em °C')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:converter,child:const Text('Converter')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(resultado)])));}
